every 1 min:
  plan = latest_plan_if_fresh(max_age = 30 min)
  if plan:
      set_charge_kw(plan.kw[now_slot])
  else:                                 # cloud unreachable or stale
      need = reserved_next_2h() + min_ready
      if ready_count() < need:
          charge_max()                  # service first
      elif local_price() < threshold or surplus_flag():
          charge_max()                  # cheap or surplus power
      else:
          charge_off()
